insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Nested loops — pyramid pattern', '// Outer loop = rows, inner loops = what each row prints.
// Internalise this and matrices, DP tables and brute-force scans stop
// feeling intimidating.
static void pyramid(int n) {
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s < n - i; s++) System.out.print(" ");
        for (int k = 0; k < 2 * i - 1; k++) System.out.print("*");
        System.out.println();
    }
}

// Fast IO for competitive input sizes — Scanner is far too slow past ~10^5.
BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
int n = Integer.parseInt(br.readLine().trim());' from topics t, languages l where t.slug = 'basics-patterns' and l.code = 'java' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Nested loops — pyramid pattern', '# Outer loop = rows, inner expressions = what each row prints.
# Python lets you say this declaratively, but write the loops out first —
# the point is to make nested iteration automatic.
def pyramid(n: int) -> None:
    for i in range(1, n + 1):
        print('' '' * (n - i) + ''*'' * (2 * i - 1))

# Fast IO. input() is slow in loops; sys.stdin is what you want past ~10^5 lines.
import sys
data = sys.stdin.buffer.read().split()
n = int(data[0])' from topics t, languages l where t.slug = 'basics-patterns' and l.code = 'py' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Nested loops and fast IO', '#include <stdio.h>

/* Outer loop = rows, inner loops = what each row prints. */
void pyramid(int n) {
    for (int i = 1; i <= n; i++) {
        for (int s = 0; s < n - i; s++) putchar('' '');
        for (int k = 0; k < 2 * i - 1; k++) putchar(''*'');
        putchar(''\n'');
    }
}

/* scanf is fine, but getchar_unlocked-style manual parsing is much faster
   when input runs to 10^6 numbers. */
int readInt(void) {
    int c = getchar(), sign = 1, x = 0;
    while (c == '' '' || c == ''\n'' || c == ''\r'') c = getchar();
    if (c == ''-'') { sign = -1; c = getchar(); }
    while (c >= ''0'' && c <= ''9'') { x = x * 10 + (c - ''0''); c = getchar(); }
    return x * sign;
}' from topics t, languages l where t.slug = 'basics-patterns' and l.code = 'c' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Nested loops and fast IO', '// Outer loop = rows, inner loops = what each row prints.
func pyramid(n int) {
	for i := 1; i <= n; i++ {
		fmt.Print(strings.Repeat(" ", n-i))
		fmt.Println(strings.Repeat("*", 2*i-1))
	}
}

// fmt.Scan is slow in loops. bufio.Scanner with a word split is the
// competitive-programming default in Go.
func newReader() *bufio.Scanner {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	sc.Split(bufio.ScanWords)
	return sc
}

func readInt(sc *bufio.Scanner) int {
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	return n
}' from topics t, languages l where t.slug = 'basics-patterns' and l.code = 'go' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Two pointers — reverse in place', 'void reverse(vector<int>& a) {
    int l = 0, r = a.size() - 1;
    while (l < r) {
        swap(a[l], a[r]);
        l++; r--;
    }
}' from topics t, languages l where t.slug = 'arrays' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Sliding window — max sum of size k', 'int maxSum(vector<int>& a, int k) {
    int sum = 0;
    for (int i = 0; i < k; i++) sum += a[i];
    int best = sum;
    for (int i = k; i < (int)a.size(); i++) {
        sum += a[i] - a[i - k];   // slide: add new, drop old
        best = max(best, sum);
    }
    return best;
}' from topics t, languages l where t.slug = 'arrays' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Prefix sum — O(1) range queries', 'vector<long long> buildPrefix(vector<int>& a) {
    int n = a.size();
    vector<long long> pre(n + 1, 0);
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
    return pre;   // sum(l..r) = pre[r+1] - pre[l]
}' from topics t, languages l where t.slug = 'arrays' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Kadane — maximum subarray sum', 'int maxSubArray(vector<int>& a) {
    int best = a[0], cur = a[0];
    for (int i = 1; i < (int)a.size(); i++) {
        cur = max(a[i], cur + a[i]);
        best = max(best, cur);
    }
    return best;
}' from topics t, languages l where t.slug = 'arrays' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Kadane''s maximum subarray', '// Keep the best sum ending here; restart whenever carrying the prefix
// forward is worse than starting fresh.
static int maxSubArray(int[] nums) {
    int best = nums[0], cur = nums[0];
    for (int i = 1; i < nums.length; i++) {
        cur = Math.max(nums[i], cur + nums[i]);
        best = Math.max(best, cur);
    }
    return best;
}

// Prefix sums: range sum in O(1) after O(n) setup.
int[] pre = new int[nums.length + 1];
for (int i = 0; i < nums.length; i++) pre[i + 1] = pre[i] + nums[i];
// sum of nums[l..r] inclusive:
int sum = pre[r + 1] - pre[l];' from topics t, languages l where t.slug = 'arrays' and l.code = 'java' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Kadane''s maximum subarray', '# Keep the best sum ending here; restart whenever carrying the prefix
# forward is worse than starting fresh.
def max_subarray(nums: list[int]) -> int:
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

