insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Binary search and binary search on the answer', '/* lo + (hi - lo) / 2 rather than (lo + hi) / 2: the latter overflows once
   lo + hi exceeds INT_MAX, and signed overflow in C is undefined behaviour —
   not merely a wrong answer. */
int binarySearch(const int *a, int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

/* lower_bound: first index with a[i] >= target (n when none). */
int lowerBound(const int *a, int n, int target) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

/* Binary search on the answer: smallest value for which feasible() holds.
   The predicate must be monotonic. */
int minFeasible(int lo, int hi, int (*feasible)(int)) {
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible(mid)) hi = mid;
        else lo = mid + 1;
    }
    return lo;
}' from topics t, languages l where t.slug = 'binary-search' and l.code = 'c' on conflict (topic_id, language_id, label) do update set code = excluded.code;
