// and a way to combine. Draw the recursion tree before coding.
static int fib(int n, int[] memo) {
    if (n <= 1) return n;
    if (memo[n] != 0) return memo[n];
    return memo[n] = fib(n - 1, memo) + fib(n - 2, memo);
}

// Subsets: at each index, either take the element or don''t.
static void subsets(int[] nums, int i, List<Integer> cur, List<List<Integer>> out) {
    if (i == nums.length) { out.add(new ArrayList<>(cur)); return; }
    subsets(nums, i + 1, cur, out);          // skip
    cur.add(nums[i]);
    subsets(nums, i + 1, cur, out);          // take
    cur.remove(cur.size() - 1);              // undo — this is the backtrack
}' from topics t, languages l where t.slug = 'recursion' and l.code = 'java' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Recursion — base case, recurse, combine', '# Python''s default recursion limit is 1000. Deep recursion needs either
