import sys
sys.setrecursionlimit(300_000)

from functools import cache

@cache                              # memoisation for free
def fib(n: int) -> int:
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

# Subsets: at each index, take the element or don''t.
def subsets(nums: list[int]) -> list[list[int]]:
    out: list[list[int]] = []

    def go(i: int, cur: list[int]) -> None:
        if i == len(nums):
            out.append(cur[:])      # copy — cur is mutated on the way back up
            return
        go(i + 1, cur)              # skip
        cur.append(nums[i])
        go(i + 1, cur)              # take
        cur.pop()                   # undo

    go(0, [])
    return out' from topics t, languages l where t.slug = 'recursion' and l.code = 'py' on conflict (topic_id, language_id, label) do update set code = excluded.code;
