// backtracking rather than plain recursion.
static void permute(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> out) {
    if (cur.size() == nums.length) { out.add(new ArrayList<>(cur)); return; }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true; cur.add(nums[i]);        // choose
        permute(nums, used, cur, out);           // explore
        cur.remove(cur.size() - 1); used[i] = false; // un-choose
    }
}

// N-Queens: the pruning is the whole algorithm. Track occupied columns and
// both diagonals so a conflict is O(1) to detect.
boolean[] col = new boolean[n], diag = new boolean[2 * n], anti = new boolean[2 * n];
// for cell (r, c): diag index r + c, anti index r - c + n' from topics t, languages l where t.slug = 'backtracking' and l.code = 'java' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Backtracking template', '# choose -> explore -> un-choose. The un-choose is what makes it backtracking.
def permutations(nums: list[int]) -> list[list[int]]:
    out: list[list[int]] = []
    used = [False] * len(nums)

    def go(cur: list[int]) -> None:
        if len(cur) == len(nums):
            out.append(cur[:])
            return
        for i, x in enumerate(nums):
            if used[i]:
                continue
            used[i] = True
            cur.append(x)           # choose
            go(cur)                 # explore
            cur.pop()               # un-choose
            used[i] = False

    go([])
    return out

# Combination sum: allow reuse by passing i (not i + 1); prune when over target.
def combination_sum(nums: list[int], target: int) -> list[list[int]]:
    out: list[list[int]] = []

    def go(i: int, remaining: int, cur: list[int]) -> None:
        if remaining == 0:
            out.append(cur[:]); return
        if i == len(nums) or remaining < 0:
            return
        cur.append(nums[i])
        go(i, remaining - nums[i], cur)   # reuse the same element
        cur.pop()
        go(i + 1, remaining, cur)         # move on

    go(0, target, [])
    return out' from topics t, languages l where t.slug = 'backtracking' and l.code = 'py' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Backtracking template', '#include <string.h>

/* choose -> explore -> un-choose. With manual memory the un-choose is
   usually just decrementing a length. */
void permute(int *nums, int n, int *used, int *cur, int curLen,
             void (*emit)(const int *, int)) {
    if (curLen == n) { emit(cur, curLen); return; }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        used[i] = 1; cur[curLen] = nums[i];          /* choose */
        permute(nums, n, used, cur, curLen + 1, emit); /* explore */
        used[i] = 0;                                  /* un-choose */
    }
}

/* N-Queens: the pruning IS the algorithm. Track occupied columns and both
   diagonals so a conflict is O(1) to test.
   For cell (r, c): diagonal r + c, anti-diagonal r - c + n. */
int solveQueens(int n, int row, char *col, char *diag, char *anti) {
    if (row == n) return 1;
    int count = 0;
    for (int c = 0; c < n; c++) {
        int d = row + c, ad = row - c + n;
        if (col[c] || diag[d] || anti[ad]) continue;
        col[c] = diag[d] = anti[ad] = 1;
        count += solveQueens(n, row + 1, col, diag, anti);
        col[c] = diag[d] = anti[ad] = 0;
    }
    return count;
}' from topics t, languages l where t.slug = 'backtracking' and l.code = 'c' on conflict (topic_id, language_id, label) do update set code = excluded.code;
