		if len(cur) == len(nums) {
			out = append(out, append([]int(nil), cur...)) // copy
			return
		}
		for i, x := range nums {
			if used[i] {
				continue
			}
			used[i] = true
			cur = append(cur, x) // choose
			rec()                // explore
			cur = cur[:len(cur)-1]
