insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Merge sort and quick sort', '// Merge sort: O(n log n) always, stable, needs O(n) extra space.
static void mergeSort(int[] a, int lo, int hi) {
    if (lo >= hi) return;
    int mid = lo + (hi - lo) / 2;
    mergeSort(a, lo, mid);
    mergeSort(a, mid + 1, hi);
    int[] tmp = new int[hi - lo + 1];
    int i = lo, j = mid + 1, k = 0;
    while (i <= mid && j <= hi) tmp[k++] = a[i] <= a[j] ? a[i++] : a[j++];
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi)  tmp[k++] = a[j++];
    System.arraycopy(tmp, 0, a, lo, tmp.length);
}

// Quick sort: O(n log n) average, O(n^2) worst on already-sorted input
// unless you randomise the pivot. In-place.
static int partition(int[] a, int lo, int hi) {
    int pivot = a[hi], i = lo - 1;
    for (int j = lo; j < hi; j++) if (a[j] < pivot) { i++; swap(a, i, j); }
    swap(a, i + 1, hi);
    return i + 1;
}' from topics t, languages l where t.slug = 'sorting' and l.code = 'java' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Merge sort, quick sort, and sorting by key', 'import random

# In practice use list.sort()/sorted() — Timsort, O(n log n), stable.
# Write these out to understand divide and conquer, not to use them.

def merge_sort(a: list[int]) -> list[int]:
    if len(a) <= 1:
        return a
    mid = len(a) // 2
    left, right = merge_sort(a[:mid]), merge_sort(a[mid:])
    out, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:          # <= keeps it stable
            out.append(left[i]); i += 1
        else:
            out.append(right[j]); j += 1
    out.extend(left[i:]); out.extend(right[j:])
    return out

def quick_sort(a: list[int], lo: int, hi: int) -> None:
    if lo >= hi:
        return
    r = random.randint(lo, hi)                    # randomise to dodge O(n^2)
    a[hi], a[r] = a[r], a[hi]
    pivot, i = a[hi], lo - 1
    for j in range(lo, hi):
        if a[j] < pivot:
            i += 1
            a[i], a[j] = a[j], a[i]
    a[i + 1], a[hi] = a[hi], a[i + 1]
    quick_sort(a, lo, i); quick_sort(a, i + 2, hi)

# Multi-key sort: ascending by age, then descending by score.
people.sort(key=lambda p: (p.age, -p.score))' from topics t, languages l where t.slug = 'sorting' and l.code = 'py' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Merge sort, quick sort, and qsort', '#include <stdlib.h>

/* Merge sort: O(n log n) always, stable, needs a scratch buffer. */
void mergeSort(int *a, int lo, int hi, int *tmp) {
    if (lo >= hi) return;
    int mid = lo + (hi - lo) / 2;
    mergeSort(a, lo, mid, tmp);
    mergeSort(a, mid + 1, hi, tmp);
    int i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi)  tmp[k++] = a[j++];
    for (int t = lo; t <= hi; t++) a[t] = tmp[t];
}

/* Quick sort, Lomuto partition. O(n^2) on sorted input unless the pivot is
   randomised — and sorted input is exactly what test suites feed you. */
static void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }

int partition(int *a, int lo, int hi) {
    swap(&a[lo + rand() % (hi - lo + 1)], &a[hi]);   /* randomise the pivot */
    int pivot = a[hi], i = lo - 1;
    for (int j = lo; j < hi; j++) if (a[j] < pivot) swap(&a[++i], &a[j]);
    swap(&a[i + 1], &a[hi]);
    return i + 1;
}

void quickSort(int *a, int lo, int hi) {
    if (lo >= hi) return;
    int p = partition(a, lo, hi);
    quickSort(a, lo, p - 1);
    quickSort(a, p + 1, hi);
}' from topics t, languages l where t.slug = 'sorting' and l.code = 'c' on conflict (topic_id, language_id, label) do update set code = excluded.code;
