insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Reverse, and Floyd''s cycle detection', 'static class ListNode { int val; ListNode next; ListNode(int v) { val = v; } }

// Reverse: walk forward rewiring each next pointer backwards.
static ListNode reverse(ListNode head) {
    ListNode prev = null;
    while (head != null) {
        ListNode next = head.next;   // save before clobbering
        head.next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

