/* Reverse: rewire each next backwards while walking forward. */
Node *reverse(Node *head) {
    Node *prev = NULL;
    while (head) {
        Node *next = head->next;   /* save before clobbering */
        head->next = prev;
        prev = head;
        head = next;
    }
    return prev;
}

/* Floyd: meeting means a cycle. Reset one pointer to head, step both by 1,
   and they meet at the cycle entry. */
Node *cycleStart(Node *head) {
    Node *slow = head, *fast = head;
    while (fast && fast->next) {
        slow = slow->next; fast = fast->next->next;
        if (slow == fast) {
            slow = head;
            while (slow != fast) { slow = slow->next; fast = fast->next; }
            return slow;
        }
    }
    return NULL;
}

/* You own the memory. Save next BEFORE freeing — reading n->next after
   free(n) is undefined behaviour, and it often appears to work. */
void list_free(Node *head) {
