insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Array-backed stack, queue, and monotonic stack', '/* A stack is an array plus a top index. */
typedef struct { int *data; int top, cap; } Stack;

void st_push(Stack *s, int x) { s->data[++s->top] = x; }
int  st_pop(Stack *s)         { return s->data[s->top--]; }
int  st_peek(const Stack *s)  { return s->data[s->top]; }
int  st_empty(const Stack *s) { return s->top < 0; }   /* init top = -1 */

/* A queue needs head and tail. Wrap them modulo cap (a circular buffer),
   otherwise the array is exhausted after cap total pushes even if empty. */
typedef struct { int *data; int head, tail, count, cap; } Queue;

void q_push(Queue *q, int x) {
    q->data[q->tail] = x;
    q->tail = (q->tail + 1) % q->cap;
    q->count++;
}

int q_pop(Queue *q) {
    int x = q->data[q->head];
    q->head = (q->head + 1) % q->cap;
    q->count--;
    return x;
}

/* Monotonic stack — next greater element. Each index is pushed and popped
   at most once, so O(n). */
void nextGreater(const int *a, int n, int *res) {
    int *st = malloc((size_t) n * sizeof *st);
    int top = -1;
    for (int i = 0; i < n; i++) res[i] = -1;
    for (int i = 0; i < n; i++) {
        while (top >= 0 && a[st[top]] < a[i]) res[st[top--]] = a[i];
        st[++top] = i;
    }
    free(st);
