insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'BST insert, search, validate', '# BST invariant: everything left < node < everything right — against INHERITED
# bounds, not just the parent. Comparing only with the parent is the classic
# wrong answer, and it passes small tests.
def is_valid(root: TreeNode | None,
             lo: float = float(''-inf''),
             hi: float = float(''inf'')) -> bool:
    if not root:
        return True
    if not (lo < root.val < hi):
        return False
    return is_valid(root.left, lo, root.val) and is_valid(root.right, root.val, hi)

def insert(root: TreeNode | None, v: int) -> TreeNode:
    if not root:
        return TreeNode(v)
    if v < root.val:
        root.left = insert(root.left, v)
    elif v > root.val:
        root.right = insert(root.right, v)
    return root

# LCA in a BST: the first node that splits the two values.
def lca(root: TreeNode | None, p: int, q: int) -> TreeNode | None:
    while root:
        if p < root.val and q < root.val:
            root = root.left
        elif p > root.val and q > root.val:
            root = root.right
        else:
            return root
    return None

# An inorder walk of a BST is sorted — that fact solves a lot of problems.' from topics t, languages l where t.slug = 'bst' and l.code = 'py' on conflict (topic_id, language_id, label) do update set code = excluded.code;
