int isValid(TreeNode *r, long lo, long hi) {
    if (!r) return 1;
    if (r->val <= lo || r->val >= hi) return 0;
    return isValid(r->left, lo, r->val) && isValid(r->right, r->val, hi);
}
/* call as isValid(root, LONG_MIN, LONG_MAX) — a long avoids the edge case
   where a node legitimately holds INT_MIN or INT_MAX */

TreeNode *insert(TreeNode *r, int v) {
    if (!r) {
        TreeNode *n = malloc(sizeof *n);
        if (!n) exit(1);
        n->val = v; n->left = n->right = NULL;
        return n;
    }
    if (v < r->val) r->left = insert(r->left, v);
    else if (v > r->val) r->right = insert(r->right, v);
    return r;
}

/* LCA in a BST: the first node that splits the two values. */
TreeNode *lca(TreeNode *r, int p, int q) {
    while (r) {
        if (p < r->val && q < r->val) r = r->left;
        else if (p > r->val && q > r->val) r = r->right;
        else return r;
    }
    return NULL;
