func twoSum(nums []int, target int) []int {
	seen := make(map[int]int, len(nums)) // value -> index
	for i, x := range nums {
		if j, ok := seen[target-x]; ok {
			return []int{j, i}
		}
		seen[x] = i
	}
	return nil
}

// Subarray sum equals K. The count[0] = 1 seed accounts for a prefix that is
// itself the answer; without it you miss every subarray starting at index 0.
func subarraySum(nums []int, k int) int {
	count := map[int]int{0: 1}
	sum, res := 0, 0
	for _, x := range nums {
		sum += x
		res += count[sum-k] // absent key yields 0 — convenient here
		count[sum]++
	}
	return res
}

// Group anagrams: a sorted-letters string is a canonical key.
func groupAnagrams(words []string) [][]string {
	groups := map[string][]string{}
	for _, w := range words {
		b := []byte(w)
		slices.Sort(b)
		groups[string(b)] = append(groups[string(b)], w)
	}
	out := make([][]string, 0, len(groups))
	for _, g := range groups {
		out = append(out, g)
	}
	return out
