insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Greedy — sort, then take the locally safe choice', '// Activity selection / non-overlapping intervals: sort by END time.
// Sorting by start or by duration both fail — the proof is that finishing
// earliest leaves the most room for everything after it.
static int maxNonOverlapping(int[][] intervals) {
    Arrays.sort(intervals, Comparator.comparingInt(x -> x[1]));
    int count = 0, lastEnd = Integer.MIN_VALUE;
    for (int[] iv : intervals) {
        if (iv[0] >= lastEnd) { count++; lastEnd = iv[1]; }
    }
    return count;
}

// Jump game: track the furthest index reachable so far.
static boolean canJump(int[] nums) {
    int reach = 0;
    for (int i = 0; i < nums.length; i++) {
        if (i > reach) return false;
        reach = Math.max(reach, i + nums[i]);
    }
    return true;
