typedef struct { int start, end; } Interval;

/* Activity selection: sort by END time. Sorting by start or by duration both
   fail; finishing earliest leaves the most room for what follows. */
static int cmp_end(const void *p, const void *q) {
    int a = ((const Interval *) p)->end, b = ((const Interval *) q)->end;
    return (a > b) - (a < b);       /* not a - b: that can overflow */
}

int maxNonOverlapping(Interval *iv, int n) {
    qsort(iv, (size_t) n, sizeof *iv, cmp_end);
    int count = 0, lastEnd = INT_MIN;
    for (int i = 0; i < n; i++) {
        if (iv[i].start >= lastEnd) { count++; lastEnd = iv[i].end; }
    }
    return count;
}

/* Jump game: track the furthest reachable index. */
int canJump(const int *nums, int n) {
    int reach = 0;
    for (int i = 0; i < n; i++) {
        if (i > reach) return 0;
        if (i + nums[i] > reach) reach = i + nums[i];
    }
    return 1;
