insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Topological sort (Kahn''s, BFS)', 'vector<int> topoSort(int n, vector<vector<int>>& adj) {
    vector<int> indeg(n, 0), order;
    for (int u = 0; u < n; u++)
        for (int v : adj[u]) indeg[v]++;
    queue<int> q;
    for (int i = 0; i < n; i++) if (!indeg[i]) q.push(i);
    while (!q.empty()) {
        int u = q.front(); q.pop(); order.push_back(u);
        for (int v : adj[u]) if (--indeg[v] == 0) q.push(v);
    }
    return order;   // size < n means a cycle exists
}' from topics t, languages l where t.slug = 'graphs' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
