insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Adjacency list, BFS, topological sort', '#include <stdlib.h>
#include <string.h>

/* Without vectors, the standard trick is a head/next edge list (''forward
   star''): one array of edge heads per node, one next-pointer per edge.
   No per-node allocation, cache friendly. */
typedef struct { int *head, *next, *to; int edgeCount; } Graph;

void g_init(Graph *g, int n, int m) {
    g->head = malloc((size_t) n * sizeof *g->head);
    g->next = malloc((size_t) m * sizeof *g->next);
    g->to   = malloc((size_t) m * sizeof *g->to);
    for (int i = 0; i < n; i++) g->head[i] = -1;   /* -1 == no edges */
    g->edgeCount = 0;
}

void g_add(Graph *g, int u, int v) {
    int e = g->edgeCount++;
    g->to[e] = v;
    g->next[e] = g->head[u];    /* push onto u''s list */
    g->head[u] = e;
}

/* BFS gives shortest path in an UNWEIGHTED graph. Set dist on ENQUEUE, not
   on dequeue, or nodes get queued repeatedly. */
void bfs(const Graph *g, int n, int src, int *dist) {
    for (int i = 0; i < n; i++) dist[i] = -1;
    int *q = malloc((size_t) n * sizeof *q);
    int head = 0, tail = 0;
    dist[src] = 0; q[tail++] = src;
    while (head < tail) {
        int u = q[head++];
        for (int e = g->head[u]; e != -1; e = g->next[e]) {
            int v = g->to[e];
            if (dist[v] == -1) { dist[v] = dist[u] + 1; q[tail++] = v; }
        }
    }
    free(q);
}

/* Kahn''s topological sort: repeatedly take a node with in-degree 0.
   Fewer than n emitted means a cycle. */' from topics t, languages l where t.slug = 'graphs' and l.code = 'c' on conflict (topic_id, language_id, label) do update set code = excluded.code;
