adj := make([][]int, n)
adj[u] = append(adj[u], v)

// BFS gives shortest path in an UNWEIGHTED graph. Mark distance on ENQUEUE,
// not on dequeue, or nodes get queued repeatedly.
func bfs(adj [][]int, src int) []int {
	dist := make([]int, len(adj))
	for i := range dist {
		dist[i] = -1
	}
	dist[src] = 0
	q := []int{src}
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		for _, v := range adj[u] {
			if dist[v] == -1 {
				dist[v] = dist[u] + 1
				q = append(q, v)
			}
		}
	}
	return dist
}

// Kahn''s topological sort. Fewer than n nodes out means there is a cycle.
func topoSort(adj [][]int) []int {
	n := len(adj)
	indeg := make([]int, n)
	for u := 0; u < n; u++ {
		for _, v := range adj[u] {
			indeg[v]++
		}
	}
	var q []int
	for i := 0; i < n; i++ {
		if indeg[i] == 0 {
			q = append(q, i)
		}
	}
	var order []int
	for len(q) > 0 {
		u := q[0]
		q = q[1:]
		order = append(order, u)
		for _, v := range adj[u] {
			indeg[v]--
			if indeg[v] == 0 {
				q = append(q, v)
			}
		}
	}
	if len(order) != n {
		return nil // cycle
	}
	return order
}' from topics t, languages l where t.slug = 'graphs' and l.code = 'go' on conflict (topic_id, language_id, label) do update set code = excluded.code;
