insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Memoisation to tabulation to rolling array', '// The progression to practise on every DP: recursion -> memo -> table -> O(1) space.

// 1. Top-down (memoised recursion).
static int robMemo(int[] a, int i, Integer[] memo) {
    if (i >= a.length) return 0;
    if (memo[i] != null) return memo[i];
    return memo[i] = Math.max(a[i] + robMemo(a, i + 2, memo), robMemo(a, i + 1, memo));
}

// 2. Bottom-up table.
static int robTab(int[] a) {
    int n = a.length;
    int[] dp = new int[n + 2];
    for (int i = n - 1; i >= 0; i--) dp[i] = Math.max(a[i] + dp[i + 2], dp[i + 1]);
    return dp[0];
}

// 3. Rolling — only the last two states are ever read.
static int rob(int[] a) {
    int take = 0, skip = 0;
    for (int i = a.length - 1; i >= 0; i--) {
        int cur = Math.max(a[i] + skip, take);
        skip = take; take = cur;
    }
    return take;
}

// 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used once.
int[] dp = new int[cap + 1];
for (int i = 0; i < n; i++)
    for (int w = cap; w >= wt[i]; w--)
        dp[w] = Math.max(dp[w], val[i] + dp[w - wt[i]]);' from topics t, languages l where t.slug = 'dynamic-programming' and l.code = 'java' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Memoisation to tabulation to rolling array', 'from functools import cache

# 1. Top-down. @cache turns naive recursion into memoised DP for free —
#    the fastest way to get a correct baseline in an interview.
@cache
def rob(i: int) -> int:
    if i >= len(nums):
        return 0
    return max(nums[i] + rob(i + 2), rob(i + 1))

# 2. Bottom-up table.
def rob_tab(nums: list[int]) -> int:
    n = len(nums)
    dp = [0] * (n + 2)
    for i in range(n - 1, -1, -1):
        dp[i] = max(nums[i] + dp[i + 2], dp[i + 1])
    return dp[0]

# 3. Rolling — only two states are ever read.
def rob_rolling(nums: list[int]) -> int:
    take = skip = 0
    for x in reversed(nums):
        take, skip = max(x + skip, take), take
    return take

# 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used at most once;
# going upward silently turns it into the unbounded version.
def knapsack(wt: list[int], val: list[int], cap: int) -> int:
    dp = [0] * (cap + 1)
    for w_i, v_i in zip(wt, val):
        for w in range(cap, w_i - 1, -1):
            dp[w] = max(dp[w], v_i + dp[w - w_i])
    return dp[cap]

# LCS — the template for most string DP.
def lcs(a: str, b: str) -> int:
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            dp[i][j] = dp[i - 1][j - 1] + 1 if a[i - 1] == b[j - 1] \
                       else max(dp[i - 1][j], dp[i][j - 1])
    return dp[len(a)][len(b)]' from topics t, languages l where t.slug = 'dynamic-programming' and l.code = 'py' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Tabulation and rolling arrays', '#include <stdlib.h>
#include <string.h>

/* In C, prefer bottom-up tables: no recursion depth risk, and the memory is
   explicit. Note calloc zeroes for you; malloc does NOT — reading
   uninitialised memory is the classic DP bug here. */
int climbStairs(int n) {
    if (n <= 2) return n;
    int prev = 1, cur = 2;
    for (int i = 3; i <= n; i++) {
        int next = prev + cur;      /* rolling: only two states are read */
        prev = cur; cur = next;
    }
    return cur;
}

/* 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used at most
   once; upward silently becomes the unbounded version. */
int knapsack(const int *wt, const int *val, int n, int cap) {
    int *dp = calloc((size_t) cap + 1, sizeof *dp);
    for (int i = 0; i < n; i++)
        for (int w = cap; w >= wt[i]; w--) {
            int cand = val[i] + dp[w - wt[i]];
            if (cand > dp[w]) dp[w] = cand;
        }
    int best = dp[cap];
    free(dp);
    return best;
}

/* 2-D tables: allocate one flat block and index it yourself. An array of
   row pointers costs an extra indirection and fragments the heap. */
int *dp = calloc((size_t) rows * cols, sizeof *dp);
#define DP(i, j) dp[(size_t)(i) * cols + (j)]' from topics t, languages l where t.slug = 'dynamic-programming' and l.code = 'c' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Memoisation to tabulation to rolling array', '// 1. Top-down with a memo map (or slice, when the state is a small int).
func robMemo(a []int, i int, memo []int) int {
	if i >= len(a) {
		return 0
	}
	if memo[i] != -1 {
		return memo[i]
	}
	memo[i] = max(a[i]+robMemo(a, i+2, memo), robMemo(a, i+1, memo))
	return memo[i]
}

// 2. Bottom-up table.
func robTab(a []int) int {
	n := len(a)
	dp := make([]int, n+2)
	for i := n - 1; i >= 0; i-- {
		dp[i] = max(a[i]+dp[i+2], dp[i+1])
	}
	return dp[0]
}

// 3. Rolling — only two states are ever read.
func rob(a []int) int {
	take, skip := 0, 0
	for i := len(a) - 1; i >= 0; i-- {
		take, skip = max(a[i]+skip, take), take
	}
	return take
}

// 0/1 knapsack, 1-D. Iterate weight DOWNWARD so each item is used once;
// upward silently becomes the unbounded version.
func knapsack(wt, val []int, cap int) int {
	dp := make([]int, cap+1)
	for i := range wt {
		for w := cap; w >= wt[i]; w-- {
			dp[w] = max(dp[w], val[i]+dp[w-wt[i]])
		}
	}
	return dp[cap]
}' from topics t, languages l where t.slug = 'dynamic-programming' and l.code = 'go' on conflict (topic_id, language_id, label) do update set code = excluded.code;
