    int c = 0;
    while (x) { x &= (x - 1); c++; }
    return c;
}' from topics t, languages l where t.slug = 'bit-manipulation' and l.code = 'cpp' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Bit tricks worth memorising', '// Java has no unsigned int. For right shifts on values that may be negative,
// use >>> (logical) rather than >> (arithmetic, sign-extending).
int x = 0b1011;

boolean isSet   = (x & (1 << k)) != 0;
int set         = x | (1 << k);
int clear       = x & ~(1 << k);
int toggle      = x ^ (1 << k);

boolean isPow2  = x > 0 && (x & (x - 1)) == 0;   // only one bit set
int lowestBit   = x & -x;                       // isolate lowest set bit
int dropLowest  = x & (x - 1);                  // clear lowest set bit
int bits        = Integer.bitCount(x);          // popcount

// XOR: a ^ a == 0 and a ^ 0 == a, so XOR-ing everything leaves the element
// that appears an odd number of times.
static int singleNumber(int[] nums) {
    int r = 0;
    for (int n : nums) r ^= n;
    return r;
}

// Iterate every subset of an n-element set.
for (int mask = 0; mask < (1 << n); mask++)
    for (int i = 0; i < n; i++)
        if ((mask & (1 << i)) != 0) { /* i is in this subset */ }' from topics t, languages l where t.slug = 'bit-manipulation' and l.code = 'java' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Bit tricks worth memorising', '# Python ints are arbitrary precision and there is no unsigned type, so
# right-shifting a negative number keeps its sign forever. Mask with
# & 0xFFFFFFFF when you need 32-bit semantics.
x = 0b1011

is_set     = bool(x & (1 << k))
set_bit    = x | (1 << k)
clear_bit  = x & ~(1 << k)
toggle     = x ^ (1 << k)

is_pow2    = x > 0 and x & (x - 1) == 0   # only one bit set
lowest     = x & -x                       # isolate lowest set bit
drop_lowest = x & (x - 1)                 # clear lowest set bit
bits       = x.bit_count()                # popcount (3.10+); else bin(x).count(''1'')

# XOR: a ^ a == 0 and a ^ 0 == a, so XOR-ing everything leaves the value that
# appears an odd number of times.
from functools import reduce
import operator
single = reduce(operator.xor, nums, 0)

# Iterate every subset of an n-element set.
for mask in range(1 << n):
    subset = [xs[i] for i in range(n) if mask & (1 << i)]' from topics t, languages l where t.slug = 'bit-manipulation' and l.code = 'py' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Bit tricks, and the undefined behaviour to avoid', '/* C is where bit manipulation is most natural and most dangerous. Use
   unsigned for anything involving shifts: shifting a signed value left into
   the sign bit is undefined behaviour, as is shifting by >= the width. */
unsigned x = 0b1011u;

int isSet      = (x >> k) & 1u;
unsigned set   = x | (1u << k);      /* 1u, not 1 — 1 << 31 on int is UB */
unsigned clear = x & ~(1u << k);
unsigned tog   = x ^ (1u << k);

int isPow2      = x && !(x & (x - 1));   /* only one bit set */
unsigned lowest = x & -x;                 /* isolate lowest set bit */
unsigned drop   = x & (x - 1);            /* clear lowest set bit */

/* popcount: __builtin_popcount on GCC/Clang, or count manually. */
int bits = __builtin_popcount(x);

int popcount(unsigned v) {
    int c = 0;
    while (v) { v &= v - 1; c++; }        /* runs once per SET bit */
    return c;
}

/* XOR: a^a == 0 and a^0 == a, so XOR-ing everything leaves the value that
   appears an odd number of times. O(1) space. */
int singleNumber(const int *nums, int n) {
    int r = 0;
    for (int i = 0; i < n; i++) r ^= nums[i];
    return r;
}

/* Iterate every subset of an n-element set. */
for (unsigned mask = 0; mask < (1u << n); mask++)
    for (int i = 0; i < n; i++)
        if (mask & (1u << i)) { /* i is in this subset */ }' from topics t, languages l where t.slug = 'bit-manipulation' and l.code = 'c' on conflict (topic_id, language_id, label) do update set code = excluded.code;
insert into code_snippets (topic_id, language_id, label, code) select t.id, l.id, 'Bit tricks worth memorising', '// Go has both signed and unsigned types, and shifts on signed values are
// arithmetic. Use uint when you want logical shifts.
x := 0b1011

isSet := x&(1<<k) != 0
set := x | (1 << k)
clear := x & ^(1 << k) // Go spells it &^ or & ^
toggle := x ^ (1 << k)

isPow2 := x > 0 && x&(x-1) == 0 // only one bit set
lowest := x & -x                // isolate lowest set bit
dropLowest := x & (x - 1)       // clear lowest set bit
bits := bits.OnesCount(uint(x)) // math/bits: popcount

// XOR: a^a == 0 and a^0 == a, so XOR-ing everything leaves the value
// appearing an odd number of times.
func singleNumber(nums []int) int {
	r := 0
	for _, n := range nums {
		r ^= n
	}
	return r
}

// Iterate every subset of an n-element set.
for mask := 0; mask < 1<<n; mask++ {
	for i := 0; i < n; i++ {
		if mask&(1<<i) != 0 {
			_ = i // i is in this subset
		}
	}
}' from topics t, languages l where t.slug = 'bit-manipulation' and l.code = 'go' on conflict (topic_id, language_id, label) do update set code = excluded.code;

insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 1, 'Setup & Program Skeleton', 'Use GCC or Clang and always compile with warnings on — `-Wall -Wextra` catches a large share of beginner bugs at compile time rather than as a mysterious crash. Add `-fsanitize=address,undefined` while learning: it turns silent memory corruption into a clear error message with a line number, which is the single most useful thing you can do for yourself in C.', '#include <stdio.h>

int main(void) {          /* (void), not () — it means ''takes no arguments'' */
    printf("Hello\n");
    return 0;
}

/* Compile like this while learning:
     gcc -std=c17 -Wall -Wextra -g -fsanitize=address,undefined main.c -o main
   The sanitizers turn undefined behaviour into a readable error instead of
   a wrong answer that only fails on the judge. */' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 2, 'Input / Output', '`scanf`/`printf` are format-string based, and getting the specifier wrong is undefined behaviour rather than a type error. `scanf` returns the number of items it successfully read — check it. For large inputs, character-level parsing with `getchar` is dramatically faster than `scanf`.', 'int n;
if (scanf("%d", &n) != 1) return 1;    /* ALWAYS check the return value */

long long big;
scanf("%lld", &big);                    /* %lld for long long, not %d */
double d;
scanf("%lf", &d);                       /* %lf to READ, %f to print */

char buf[128];
scanf("%127s", buf);                    /* bound it, or you overflow */

/* Reading a whole line: fgets keeps the ''\n'', so strip it. */
if (fgets(buf, sizeof buf, stdin)) {
    buf[strcspn(buf, "\n")] = ''\0'';
}

/* Fast integer reader for large inputs. */
int readInt(void) {
    int c = getchar(), sign = 1, x = 0;
    while (c == '' '' || c == ''\n'' || c == ''\r'') c = getchar();
    if (c == ''-'') { sign = -1; c = getchar(); }
    while (c >= ''0'' && c <= ''9'') { x = x * 10 + (c - ''0''); c = getchar(); }
    return x * sign;
}' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 3, 'Types, Overflow & Undefined Behaviour', 'Signed integer overflow in C is *undefined behaviour*, not wraparound — the compiler is permitted to assume it never happens and optimise accordingly, so the symptom can be far stranger than a wrong number. Use `long long` for anything that might exceed ~2.1e9, and prefer `unsigned` for bit manipulation, where wraparound IS defined.', '#include <stdint.h>
#include <limits.h>

int i = 42;
long long big = 1000000007LL;
unsigned u = 0u;
double d = 3.14;
char c = ''a'';

/* Fixed-width types when size matters. */
int32_t exact32;
int64_t exact64;

/* Overflow: promote BEFORE multiplying. */
int a = 100000, b = 100000;
long long ok = (long long) a * b;      /* correct */
/* int bad = a * b;  <- UNDEFINED behaviour, not just wrong */

printf("%d\n", INT_MAX);               /* 2147483647 */

/* Integer division truncates toward zero (unlike Python''s floor). */
printf("%d\n", -7 / 2);                /* -3 */
printf("%d\n", -7 % 2);                /* -1 */

/* sizeof yields size_t — print it with %zu. */
printf("%zu\n", sizeof(int));' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 4, 'Control Flow', 'Standard C-family control flow. The classic traps: `switch` falls through unless you `break`, an `if` without braces controls only the next statement, and assignment inside a condition (`if (x = 5)`) compiles happily. Turn on `-Wall` and it warns about most of these.', 'for (int i = 0; i < n; i++) { }
while (cond) { }
do { } while (cond);

/* switch falls through — deliberate here, a bug otherwise. */
switch (op) {
    case ''+'': r = a + b; break;
    case ''-'': r = a - b; break;
    case ''x'':
    case ''*'': r = a * b; break;    /* intentional fall-through */
    default:  r = 0;
}

/* Always brace your bodies. Without braces only ONE statement is guarded. */
if (cond) {
    doThis();
    doThat();          /* without braces this runs unconditionally */
}

/* goto is genuinely idiomatic in C for breaking out of nested loops
   and for centralised cleanup. */
for (int r = 0; r < rows; r++)
    for (int col = 0; col < cols; col++)
        if (grid[r][col] == target) goto found;
found:;' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 5, 'Pointers & Functions', 'A pointer holds an address. `*p` reads through it, `&x` takes the address of `x`. C is strictly pass-by-value, so to let a function modify your variable you pass its address. Arrays decay to pointers when passed, which means the function has no idea how long the array is — you must pass the length too.', 'int x = 5;
int *p = &x;      /* p points at x */
*p = 10;          /* x is now 10 */

/* Pass by address to mutate the caller''s variable. */
void increment(int *v) { (*v)++; }
increment(&x);

void swap(int *a, int *b) { int t = *a; *a = *b; *b = t; }

/* Arrays decay to pointers: sizeof(a) inside the function is the POINTER
   size, not the array size. Always pass n. */
int sum(const int *a, int n) {
    int s = 0;
    for (int i = 0; i < n; i++) s += a[i];
    return s;
}

/* const says ''I will not modify this'' — use it; it documents and it catches
   mistakes at compile time. */

/* Function pointers — how qsort takes a comparator. */
int cmp(const void *p, const void *q) {
    int a = *(const int *) p, b = *(const int *) q;
    return (a > b) - (a < b);   /* not a - b: that can overflow */
}' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 6, 'Arrays & 2-D Arrays', 'Arrays are contiguous and have no length field, and there is no bounds checking whatsoever — reading `a[n]` is undefined behaviour that usually appears to work, which is why bugs surface far from their cause. For 2-D data, prefer one flat block with your own index arithmetic: it is one allocation and it is cache-friendly.', 'int a[5] = {0};              /* all zeros */
int b[] = {3, 1, 2};         /* size inferred: 3 */
int n = (int) (sizeof b / sizeof b[0]);   /* works only in this scope */

/* NO bounds checking. This is UB and may silently ''work''. */
/* printf("%d", b[10]); */

/* Fixed 2-D array — rows are contiguous. */
int grid[3][4] = {{0}};
grid[1][2] = 7;

/* Dynamic 2-D: one flat block plus a macro. Preferred. */
#include <stdlib.h>
int rows = 3, cols = 4;
int *flat = calloc((size_t) rows * cols, sizeof *flat);   /* calloc zeroes */
#define AT(i, j) flat[(size_t)(i) * cols + (j)]
AT(1, 2) = 7;
free(flat);

/* Variable-length arrays exist (C99) but live on the stack — a large one
   overflows it. Use malloc for anything big or input-sized. */' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 7, 'Strings & the NUL Terminator', 'A C string is just a `char` array whose end is marked by a `''\0''` byte. Everything follows from that: `strlen` walks the whole string to find the terminator (so never call it in a loop condition), a buffer must have room for the terminator as well as the characters, and forgetting to write it produces a string with no end.', '#include <string.h>

char s[] = "hello";        /* 6 bytes: 5 chars + ''\0'' */
char *lit = "hello";        /* points at read-only memory — do NOT modify */

size_t n = strlen(s);       /* O(n): compute ONCE, not per iteration */

strcpy(dst, src);           /* no bounds check — overflows silently */
snprintf(dst, sizeof dst, "%s", src);   /* bounded and always terminated */

strcmp(a, b) == 0;          /* equality: strcmp returns 0 when EQUAL */
strchr(s, ''l'');
strstr(s, "ell");

/* Building a string manually — remember the terminator. */
char buf[16];
int k = 0;
for (int i = 0; i < 5; i++) buf[k++] = ''a'' + i;
buf[k] = ''\0'';              /* forget this and you have no string */

/* ctype functions take an int and must receive an unsigned char —
   passing a negative char is undefined behaviour. */
#include <ctype.h>
if (isalpha((unsigned char) s[0])) { }' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 8, 'Dynamic Memory', '`malloc` gives you uninitialised bytes, `calloc` gives you zeroed bytes, `realloc` grows a block and may move it. Every allocation is yours to `free` exactly once. The three classic failures are: using memory after freeing it, freeing twice, and losing the only pointer to a block (a leak). Address Sanitizer catches all three.', '#include <stdlib.h>

int *a = malloc((size_t) n * sizeof *a);   /* sizeof *a, not sizeof(int) —
                                             survives a type change */
if (!a) { /* malloc CAN fail; handle it */ return 1; }
/* a[i] is uninitialised garbage here */

int *z = calloc((size_t) n, sizeof *z);   /* zeroed — what DP tables want */

/* realloc may move the block. Assign to a TEMP: on failure it returns NULL
   and the original pointer is still valid — ''a = realloc(a, ...)'' leaks it. */
int *grown = realloc(a, (size_t) (2 * n) * sizeof *a);
if (!grown) { free(a); return 1; }
a = grown;

free(a);
a = NULL;                  /* defensive: double-free of NULL is a no-op */

/* Never return a pointer to a local — its stack frame is gone. */
int *broken(void) { int x = 5; return &x; }        /* dangling */
int *fine(void)   { int *p = malloc(sizeof *p); *p = 5; return p; }' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 9, 'Structs & Building Containers', '`struct` groups fields; `typedef` saves you writing `struct` everywhere. Since C ships no containers, a struct plus a few functions IS your container. Growable arrays, stacks, queues, hash tables and tries are all a few dozen lines — and writing them once teaches you more than using them a hundred times elsewhere.', '#include <stdlib.h>

typedef struct { int x, y; } Point;

Point p = {1, 2};
Point q = {.x = 1, .y = 2};      /* designated initialisers, clearer */
p.x = 5;

/* Through a pointer, use -> */
Point *pp = &p;
pp->x = 7;                       /* same as (*pp).x */

/* Self-referential structs need the tag name. */
typedef struct Node {
    int val;
    struct Node *next;           /* ''Node *next'' is not yet valid here */
} Node;

/* A growable array — the vector you don''t get. */
typedef struct { int *data; size_t len, cap; } Vec;

void vec_push(Vec *v, int x) {
    if (v->len == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;    /* double: amortised O(1) */
        int *g = realloc(v->data, v->cap * sizeof *v->data);
        if (!g) { free(v->data); exit(1); }
        v->data = g;
    }
    v->data[v->len++] = x;
}' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 10, 'Common Gotchas', 'C''s failure mode is that mistakes usually *appear to work*. Out-of-bounds reads return plausible garbage, use-after-free often returns the old value, and uninitialised variables are frequently zero by luck. This is why the sanitizers are not optional while learning: they convert ''works on my machine'' into a precise error.', '/* 1. Uninitialised memory is garbage, not zero. malloc does NOT clear. */
int *dp = calloc(n, sizeof *dp);        /* use calloc for tables */

/* 2. sizeof on a parameter gives the pointer size. */
void f(int a[]) { /* sizeof a == 8, not the array length */ }

/* 3. = vs ==. This assigns and is always true. */
if (x == 5) { }                         /* compare */

/* 4. Comparing strings with == compares ADDRESSES. */
if (strcmp(a, b) == 0) { }

/* 5. Off-by-one on the terminator: a 5-char string needs 6 bytes. */
char buf[6];
snprintf(buf, sizeof buf, "hello");

/* 6. %d for a long long, or %f to read a double — both UB.
      -Wall catches format mismatches; leave it on. */

/* 7. Signed overflow is UB. Use unsigned for bit twiddling. */
unsigned mask = 1u << 31;               /* 1 << 31 on int is UB */

/* 8. Modifying a string literal is UB, even though it compiles. */
char *lit = "hello";
/* lit[0] = ''H'';   <- crashes on most platforms */
char mut[] = "hello";
mut[0] = ''H'';                           /* fine: this is an array */' from languages where code = 'c' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 1, 'Setup & Program Skeleton', 'Every competitive/DSA C++ program follows the same shape: include headers, open `main`, read input, compute, print output. `#include <bits/stdc++.h>` pulls in the entire standard library in one line (fine for practice; avoid in production). `using namespace std;` lets you write `vector` instead of `std::vector`.', '#include <bits/stdc++.h>
using namespace std;

int main() {
    // your code here
    cout << "Hello, DSA" << endl;
    return 0;
}' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 2, 'Fast Input / Output', 'Default `cin`/`cout` are slow for large inputs. Two lines at the top of `main` speed them up dramatically by unsyncing from C stdio and untying `cin` from `cout`. Use `"\n"` instead of `endl` (which flushes every time) in tight loops.', 'ios_base::sync_with_stdio(false);
cin.tie(NULL);

int n; cin >> n;
vector<int> a(n);
for (int i = 0; i < n; i++) cin >> a[i];
for (int x : a) cout << x << "\n";' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 3, 'Types, Variables & Operators', 'Know your integer ranges: `int` holds ~±2.1×10⁹; use `long long` (~±9.2×10¹⁸) when sums or products can overflow — a frequent bug source. `double` for decimals, `char` for single characters, `bool` for true/false. Operators are the usual arithmetic (`+ - * / %`), comparison (`== != < >`), and logical (`&& || !`).', 'int a = 5, b = 2;
long long big = 1LL * a * 1000000000; // force 64-bit math
cout << a / b << " " << a % b << "\n"; // 2 1  (integer division)
double d = (double)a / b;               // 2.5 (cast to divide)
bool ok = (a > b) && (b > 0);' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 4, 'Control Flow', '`if/else if/else` for branching, `for`/`while` for loops. The range-based `for (auto x : container)` is the cleanest way to iterate. Use `break` to exit a loop early and `continue` to skip to the next iteration.', 'for (int i = 0; i < 5; i++) {
    if (i % 2 == 0) continue;   // skip evens
    cout << i << " ";           // 1 3
}

int i = 0;
while (i < 3) { cout << i; i++; }  // 012' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 5, 'Functions', 'Declare the return type, name, and parameters. Pass large objects **by reference** (`vector<int>& v`) to avoid copying; add `const` if you won''t modify them. Recursion is just a function calling itself — the backbone of many DSA solutions.', 'int add(int a, int b) { return a + b; }

// pass by reference: no copy, can modify
void doubleAll(vector<int>& v) {
    for (int& x : v) x *= 2;
}

long long fact(int n) {          // recursion
    return n <= 1 ? 1 : n * fact(n - 1);
}' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 6, 'Arrays & Vectors', 'Prefer `vector` (dynamic array) over raw arrays — it grows, knows its size, and works with STL algorithms. Create, size, push, index, and iterate as shown. 2D grids are a `vector<vector<int>>`.', 'vector<int> v;             // empty
v.push_back(10);           // [10]
vector<int> w(5, 0);       // [0,0,0,0,0]
w[2] = 7;                  // index like an array
cout << w.size() << "\n";  // 5

// 2D grid: 3 rows x 4 cols of zeros
vector<vector<int>> grid(3, vector<int>(4, 0));' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 7, 'Strings', '`std::string` behaves like a vector of characters with handy extras: concatenation with `+`, `.size()`, `.substr(pos, len)`, `.find(...)`, and index access. Iterate character by character with a range-for.', 'string s = "hello";
s += " world";              // concatenate
cout << s.size() << "\n";   // 11
cout << s.substr(0, 5);      // "hello"
for (char c : s) { /* ... */ }
if (s.find("world") != string::npos) cout << "found";' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 8, 'The STL Toolkit', 'The containers you''ll use in almost every problem: `map`/`unordered_map` (key→value), `set`/`unordered_set` (unique elements), `pair` (two values), `stack`, `queue`, `priority_queue` (heap). The `unordered_` versions are O(1) average; the plain ones are sorted and O(log n).', 'unordered_map<string,int> cnt;
cnt["apple"]++;                 // auto-inserts 0 then increments

set<int> s = {3, 1, 2};        // stored sorted: 1 2 3
s.insert(5); s.count(3);        // membership test

pair<int,int> p = {1, 2};
cout << p.first << p.second;

stack<int> st; st.push(1); st.top(); st.pop();
queue<int> q; q.push(1); q.front(); q.pop();' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 9, 'Useful STL Algorithms', 'The `<algorithm>` header saves you from reinventing basics: `sort` (with an optional comparator), `reverse`, `max_element`/`min_element`, `accumulate` (sum), and the binary-search helpers `lower_bound`/`upper_bound` on sorted ranges. Learn these and your code gets shorter and less bug-prone.', 'vector<int> v = {3, 1, 4, 1, 5};
sort(v.begin(), v.end());                 // ascending
sort(v.begin(), v.end(), greater<int>()); // descending
reverse(v.begin(), v.end());
int mx = *max_element(v.begin(), v.end());
int sum = accumulate(v.begin(), v.end(), 0);
// first index >= 4 in a sorted vector:
int idx = lower_bound(v.begin(), v.end(), 4) - v.begin();' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 10, 'Common Gotchas', 'The bugs that bite everyone: integer overflow (use `long long` for big sums/products), integer division truncating (`5/2 == 2`), out-of-bounds vector access (no automatic check — undefined behavior), and uninitialized variables holding garbage. When a number can exceed ~2×10⁹, reach for `long long` before it bites you.', '// overflow: int * int can overflow before assignment
long long product = 1LL * a * b;    // force 64-bit

// division: cast to get a decimal
double avg = (double)sum / n;

// always size vectors before indexing
vector<int> v(n);   // not: vector<int> v; v[0] = ...;' from languages where code = 'cpp' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 1, 'Setup & Program Skeleton', 'Install Go and check `go version` — 1.21 or newer, which added the builtin `min`/`max` and the `slices`/`maps` packages that make DSA code far less verbose. Run a single file with `go run main.go`. Every file declares a package; the entry point is `func main()` in `package main`. Unused imports and unused local variables are compile ERRORS, not warnings.', 'package main

import "fmt"

func main() {
	fmt.Println("Hello")
}

// gofmt is not optional in practice — the whole ecosystem uses it, and
// tabs-vs-spaces arguments simply don''t happen. Run: gofmt -w main.go

// Unused variables won''t compile. Assign to _ when you genuinely mean it.
_ = someValueIDontNeedYet' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 2, 'Input / Output', '`fmt.Scan` is convenient but slow. For competitive input use a `bufio.Scanner` split on words, and give it a large buffer — the default maximum token/line size is only 64KB and it fails silently past that. Buffer output too, with `bufio.Writer` and a deferred `Flush`.', 'package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

var sc = bufio.NewScanner(os.Stdin)
var w = bufio.NewWriter(os.Stdout)

func readInt() int {
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	return n
}

func main() {
	// The default 64KB limit silently truncates big inputs — raise it.
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	sc.Split(bufio.ScanWords)
	defer w.Flush() // without this, buffered output is never written

	n := readInt()
	fmt.Fprintln(w, n)
}' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 3, 'Types, Variables & Zero Values', 'Every variable has a zero value — `0`, `""`, `false`, `nil` — so declarations are never uninitialised. `int` is 64-bit on modern platforms, which removes most overflow worry, though it still wraps rather than erroring. Go has NO implicit numeric conversion: mixing `int` and `int64` is a compile error, which is verbose but catches real bugs.', 'var i int = 42
j := 42               // short declaration, type inferred
var s string          // "" — zero value, not nil
var f float64 = 3.14
var b bool            // false
var p *int            // nil

const MOD = 1_000_000_007

// No implicit conversion — this is a compile error:
//   var x int64 = i
var x int64 = int64(i)   // explicit, always

// Integer division truncates toward zero.
fmt.Println(7 / 2)       // 3
fmt.Println(-7 / 2)      // -3  (Python would floor to -4)
fmt.Println(7 % 2)       // 1
fmt.Println(float64(7) / 2)

// min/max are builtins since 1.21 — no more hand-written helpers.
fmt.Println(max(3, 7), min(3, 7))

// Multiple return values are pervasive, especially (value, ok).
func divide(a, b int) (int, error) {
	if b == 0 {
		return 0, fmt.Errorf("divide by zero")
	}
	return a / b, nil
}' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 4, 'Control Flow', 'There is exactly one loop keyword: `for`. It covers the C-style loop, the while loop, the infinite loop, and iteration via `range`. `if` can declare a variable scoped to the statement, which is the idiomatic way to handle a `(value, ok)` pair. `switch` does NOT fall through by default — the opposite of C.', 'for i := 0; i < n; i++ { }
for i < n { }                 // this is Go''s ''while''
for { break }                 // infinite

for i, x := range nums { }    // index and value
for _, x := range nums { }    // value only
for k, v := range m { }       // map: order is RANDOMISED by design
for i := range 10 { }         // 1.22+: 0..9

// if with a scoped declaration — the standard (value, ok) shape.
if v, ok := m[key]; ok {
	fmt.Println(v)
}

// switch: no fall-through; use ''fallthrough'' explicitly if you want it.
switch {
case x < 0:
	sign = -1
case x > 0:
	sign = 1
default:
	sign = 0
}

// Labelled break to escape nested loops.
outer:
for r := range grid {
	for c := range grid[r] {
		if grid[r][c] == target {
			break outer
		}
	}
}' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 5, 'Functions, Closures & defer', 'Functions are values, so closures are the natural way to write a recursive helper that needs shared state — declare the variable first, then assign the function, or the recursive call cannot see the name. `defer` runs on function exit and is the standard way to guarantee a flush or unlock.', 'func add(a, b int) int { return a + b }

// Named results, and multiple returns.
func divmod(a, b int) (q, r int) {
	q, r = a/b, a%b
	return // naked return uses the named results
}

// Recursive closure: declare, THEN assign. Writing
//   dfs := func(u int) { dfs(...) }
// fails because dfs isn''t in scope inside its own literal.
var dfs func(u int)
dfs = func(u int) {
	visited[u] = true
	for _, v := range adj[u] {
		if !visited[v] {
			dfs(v)
		}
	}
}
dfs(0)

// defer: runs when the function returns, LIFO order.
func process() {
	defer w.Flush()
	// ... work
}

// Generics (1.18+) for the helpers the stdlib doesn''t give you.
func abs[T int | int64 | float64](x T) T {
	if x < 0 {
		return -x
	}
	return x
}' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 6, 'Arrays, Slices & the Aliasing Trap', 'An array has a fixed length that is part of its type; a slice is a view (pointer, length, capacity) over a backing array — and slices are what you actually use. The crucial consequence: two slices can share one backing array, so writing through one is visible through the other. `append` may or may not reallocate, which makes this intermittent and therefore easy to miss.', 'var arr [5]int              // ARRAY: length is part of the type, copied on assign
s := []int{3, 1, 2}         // SLICE: a view, cheap to pass
s = append(s, 4)

made := make([]int, 5)      // len 5, zeroed
buf := make([]int, 0, 100)  // len 0, cap 100 — avoids regrowth

fmt.Println(len(s), cap(s))

// Slicing shares memory — this is the trap.
a := []int{1, 2, 3, 4}
b := a[1:3]                 // [2 3], SAME backing array
b[0] = 99                   // a is now [1 99 3 4]

// Copy when you need independence.
c := make([]int, len(a))
copy(c, a)
d := append([]int(nil), a...)   // idiomatic clone

// This bites hardest in backtracking: append the slice itself and every
// result aliases the same buffer.
out = append(out, append([]int(nil), cur...))   // copy, always

// 2-D: allocate each row.
grid := make([][]int, rows)
for i := range grid {
	grid[i] = make([]int, cols)
}' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 7, 'Strings, Bytes & Runes', 'A string is an immutable slice of BYTES. Indexing gives a byte; `range` gives runes (Unicode code points) along with their byte offsets. For ASCII interview input the two coincide, so it is easy to write byte-indexing code that quietly breaks on anything else. Build strings with `strings.Builder`, never `+=` in a loop.', 'import (
	"strings"
	"strconv"
)

s := "hello"
s[0]                       // byte 104, NOT "h"
string(s[0])               // "h"
len(s)                     // BYTES
len([]rune(s))             // characters

for i, r := range s {      // i is a BYTE offset; r is a rune
	_ = i
	_ = r
}

strings.Split("a,b", ",")
strings.Join([]string{"a", "b"}, "-")
strings.Contains(s, "ell")
strings.ToUpper(s)
strings.TrimSpace(s)
strings.Repeat("ab", 3)
strconv.Itoa(42)
n, _ := strconv.Atoi("42")

// Build with a Builder: strings are immutable, so += is O(n^2).
var sb strings.Builder
for i := 0; i < n; i++ {
	sb.WriteByte(''a'')
}
result := sb.String()

// Mutating: convert to []byte (or []rune for non-ASCII), edit, convert back.
bs := []byte(s)
bs[0] = ''H''
s = string(bs)' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 8, 'Maps & Sets', 'Maps are hash tables with O(1) average access. Two things to internalise: reading a missing key returns the zero value rather than an error (so `m[k]++` just works, but you cannot tell absent from zero without the two-value form), and iteration order is deliberately randomised so you must sort keys for deterministic output.', 'import (
	"slices"
	"maps"
)

m := map[string]int{}          // or make(map[string]int)
m["a"] = 1
m["b"]++                       // zero value means no initialisation needed

v, ok := m["c"]                 // ok distinguishes absent from zero
delete(m, "a")
len(m)

// Writing to a NIL map panics; reading one is fine. Always make() it.
var nilMap map[string]int
// nilMap["x"] = 1   <- panic: assignment to entry in nil map

// Iteration order is RANDOM by design. Sort keys when output must be stable.
keys := slices.Collect(maps.Keys(m))   // 1.23+; else a manual loop
slices.Sort(keys)
for _, k := range keys {
	_ = m[k]
}

// A set is a map to empty structs — struct{} takes zero bytes.
seen := map[int]struct{}{}
seen[42] = struct{}{}
if _, exists := seen[42]; exists { }

// Adjacency list.
adj := map[int][]int{}
adj[u] = append(adj[u], v)      // append works on a nil slice' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 9, 'Sorting, slices & container/heap', 'The `slices` package (1.21+) is what you want: `slices.Sort`, `slices.BinarySearch`, `slices.Contains`, `slices.Reverse` — all generic, all concise. For a priority queue there is no ready-made type: `container/heap` supplies the algorithms and you implement five methods to supply the storage.', 'import (
	"container/heap"
	"slices"
	"sort"
)

slices.Sort(nums)
slices.Reverse(nums)
slices.Contains(nums, 3)
i, found := slices.BinarySearch(nums, 3)
slices.Max(nums); slices.Min(nums)

// Custom order: return negative / zero / positive.
slices.SortFunc(people, func(a, b Person) int {
	if a.Age != b.Age {
		return a.Age - b.Age
	}
	return b.Score - a.Score      // tie-break, descending
})

// Stable sort when equal elements must keep their order.
sort.SliceStable(xs, func(i, j int) bool { return xs[i].K < xs[j].K })

// Priority queue: implement heap.Interface.
type IntHeap []int

func (h IntHeap) Len() int           { return len(h) }
func (h IntHeap) Less(i, j int) bool { return h[i] < h[j] }  // min-heap
func (h IntHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *IntHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *IntHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

// Call heap.Push/heap.Pop — never the methods directly, or the invariant
// is not maintained.
h := &IntHeap{}
heap.Init(h)
heap.Push(h, 5)
smallest := heap.Pop(h).(int)' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 10, 'Common Gotchas', 'Go has fewer traps than C++ or Python, and the ones it has are mostly about slices sharing memory and nil maps. The compiler catches a surprising amount — unused variables, unused imports, missing conversions — so lean on it rather than fighting it.', '// 1. Slice aliasing: append the slice itself in backtracking and every
//    result points at the same buffer.
out = append(out, append([]int(nil), cur...))   // copy

// 2. append may or may not reallocate, so whether the caller sees your
//    writes is not predictable. Return the slice.
func add(s []int) []int { return append(s, 1) }
s = add(s)

// 3. Writing to a nil map panics.
m := make(map[string]int)   // not: var m map[string]int

// 4. Map iteration order is randomised — never rely on it.

// 5. Loop variable capture. Before Go 1.22 every goroutine/closure shared
//    ONE loop variable; 1.22+ gives each iteration its own.
for _, x := range nums {
	x := x                  // the pre-1.22 fix, harmless afterwards
	funcs = append(funcs, func() int { return x })
}

// 6. Integer division truncates; convert before dividing for a real result.
avg := float64(sum) / float64(len(nums))

// 7. Comparing slices with == is a compile error (only to nil is allowed).
slices.Equal(a, b)

// 8. defer runs at FUNCTION exit, not at end of block — a defer inside a
//    loop accumulates until the function returns.' from languages where code = 'go' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 1, 'Setup & Program Skeleton', 'Install a JDK (21 LTS is a good default) and check `java -version`. Since JDK 11 you can run a single file directly with `java Main.java` — no separate `javac` step — which is ideal for practice. Online judges expect the class to be named `Main` and the file to match. Everything lives inside a class; there are no free functions.', 'public class Main {
    public static void main(String[] args) {
        System.out.println("Hello");
    }
}

// Helper methods must be static to be called from static main.
static int add(int a, int b) { return a + b; }' from languages where code = 'java' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 2, 'Fast Input / Output', '`Scanner` is convenient and far too slow: it does regex parsing per token and will time out past roughly 10^5 values. Use `BufferedReader` with `StringTokenizer` for input, and buffer your output too — `System.out.println` in a tight loop flushes constantly and is a common cause of a mysterious TLE.', 'import java.io.*;
import java.util.*;

BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
int n = Integer.parseInt(br.readLine().trim());

// Several integers on one line.
StringTokenizer st = new StringTokenizer(br.readLine());
int a = Integer.parseInt(st.nextToken());
int b = Integer.parseInt(st.nextToken());

// Buffered output — build up, then flush once.
StringBuilder sb = new StringBuilder();
for (int i = 0; i < n; i++) sb.append(i).append(''\n'');
System.out.print(sb);' from languages where code = 'java' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 3, 'Types, Variables & Operators', '`int` is 32-bit and overflows silently at about 2.1 billion — no exception, just a wrong answer. Use `long` the moment sums or products could exceed that. Integer division truncates. `char` is a 16-bit UTF-16 code unit, and `char` arithmetic works, which is why `c - ''a''` is the standard way to index an alphabet array.', 'int i = 42;
long big = 1_000_000_007L;        // underscores are legal separators
double d = 3.14;
char c = ''a'';
boolean flag = true;

// Overflow: promote BEFORE multiplying, not after.
int a = 100000, b = 100000;
long bad  = a * b;                // overflows as int, then widens — wrong
long good = (long) a * b;         // correct

// Integer division truncates toward zero.
System.out.println(5 / 2);        // 2
System.out.println(5 / 2.0);      // 2.5

// Ceiling division without floating point.
int ceilDiv = (x + y - 1) / y;

// Alphabet indexing.
int idx = c - ''a'';                // 0..25' from languages where code = 'java' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 4, 'Control Flow', 'Standard C-family syntax. The enhanced `for` (`for (int x : arr)`) is cleaner when you don''t need the index. Labelled `break` lets you exit nested loops in one step, which is genuinely useful in grid problems. Modern `switch` expressions remove the fall-through footgun.', 'for (int i = 0; i < n; i++) { }
for (int x : arr) { }            // enhanced for — no index
while (cond) { }
do { } while (cond);

// Labelled break: escape both loops at once.
outer:
for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
        if (grid[r][c] == target) break outer;
    }
}

// switch expression (JDK 14+) — arrow form, no fall-through, returns a value.
int days = switch (month) {
    case 2 -> 28;
    case 4, 6, 9, 11 -> 30;
    default -> 31;
};' from languages where code = 'java' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 5, 'Methods, References & Scope', 'Java is always pass-by-value — but for objects the value passed is the reference. So a method can mutate the array or list you hand it, yet cannot make your variable point at a different object. This distinction explains most surprises about "why did my array change?" and "why didn''t my swap work?".', '// Mutating through the reference: the caller SEES this.
static void fill(int[] a) { a[0] = 99; }

// Reassigning the parameter: the caller does NOT see this.
static void reassign(int[] a) { a = new int[]{1, 2, 3}; }

// So you cannot write swap(int, int) — primitives are copied.
// Return a value, or swap inside an array.
static void swap(int[] a, int i, int j) { int t = a[i]; a[i] = a[j]; a[j] = t; }

// Varargs for a variable number of arguments.
static int sum(int... xs) {
    int s = 0;
    for (int x : xs) s += x;
    return s;
}' from languages where code = 'java' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 6, 'Arrays & 2-D Arrays', 'Arrays are fixed-length objects with a `.length` field (not a method). They are zero-initialised: `0`, `false`, or `null`. A 2-D array is an array of row references, so rows can differ in length — and copying a 2-D array with `clone()` copies only the row references, not the rows themselves.', 'int[] a = new int[5];             // all zeros
int[] b = {3, 1, 2};
System.out.println(b.length);     // field, not length()

int[][] grid = new int[3][4];      // 3 rows, 4 cols
int[][] jagged = new int[3][];     // rows allocated separately

Arrays.sort(b);
Arrays.fill(a, -1);
int[] copy = Arrays.copyOf(b, b.length);
int pos = Arrays.binarySearch(b, 2);   // array MUST be sorted
System.out.println(Arrays.toString(b));
System.out.println(Arrays.deepToString(grid));   // for nested arrays

// Shallow copy trap: rows are shared.
int[][] shallow = grid.clone();
shallow[0][0] = 99;               // also changes grid[0][0]' from languages where code = 'java' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 7, 'Strings', '`String` is immutable, so every concatenation allocates a new object — building a string with `+=` in a loop is O(n^2) and is the single most common performance mistake in Java interview code. Use `StringBuilder`. Compare with `.equals()`, never `==`: `==` compares references, and it appears to work for short literals because of the string pool, which makes the bug intermittent.', 'String s = "hello";
s.charAt(0);
s.length();
s.substring(1, 3);                // [1, 3)
s.indexOf(''l'');
s.toCharArray();
String.valueOf(42);
Integer.parseInt("42");

// Comparison: .equals for value, == for identity.
String x = "ab", y = "a" + "b";
System.out.println(x.equals(y));  // true — what you want

// Building: StringBuilder, not +=.
StringBuilder sb = new StringBuilder();
for (int i = 0; i < n; i++) sb.append(i);
sb.reverse();
String out = sb.toString();

// Char frequency over an alphabet.
int[] freq = new int[26];
for (char c : s.toCharArray()) freq[c - ''a'']++;' from languages where code = 'java' on conflict (language_id, "order") do update set section_title = excluded.section_title, body_md = excluded.body_md, code = excluded.code;
insert into lang_primer (language_id, "order", section_title, body_md, code) select id, 8, 'The Collections Framework', 'Java''s answer to the STL. Declare variables by the interface (`List`, `Map`, `Set`, `Deque`) and instantiate the implementation — it keeps your code flexible and reads better in interviews. Collections hold objects, not primitives, so `List<Integer>` autoboxes; that costs memory and time, and it means `==` between two `Integer` objects can be false.', 'List<Integer> list = new ArrayList<>();      // vector
Map<String, Integer> map = new HashMap<>();   // unordered_map
Set<Integer> set = new HashSet<>();           // unordered_set
Deque<Integer> dq = new ArrayDeque<>();       // stack AND queue
Map<String, Integer> ordered = new TreeMap<>();  // sorted, O(log n)
PriorityQueue<Integer> pq = new PriorityQueue<>(); // MIN-heap by default

// Counting idiom.
map.merge(key, 1, Integer::sum);
map.getOrDefault(key, 0);
map.computeIfAbsent(key, k -> new ArrayList<>()).add(v);

// Iterate a map.
for (Map.Entry<String, Integer> e : map.entrySet())
    System.out.println(e.getKey() + " " + e.getValue());

// Autoboxing trap: compare boxed values with .equals or intValue().
